look.customCSS:
/* ───── 棉花可可 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/80px 80px,#F7F1EA !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一层可可，底边往下淌一圈 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#7A4E36,#5E3826) !important;border-bottom:none !important;box-shadow:none !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:-11px !important;height:12px !important;background:url("data:image/svg+xml;base64,") 0 0/40px 12px repeat-x !important;pointer-events:none !important;z-index:2 !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important;font-weight:600 !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#E3CDB9 !important}
[data-wk="chatback"] svg{stroke:#fff !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important;filter:drop-shadow(0 0 0 #fff) drop-shadow(0 1px 0 rgba(255,255,255,.5)) !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-8px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;flex-shrink:0 !important;aspect-ratio:1 !important;border-radius:50% !important;box-shadow:0 0 0 3px #FFFCF7,0 0 0 5px #EADBCB !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-9px !important;bottom:-4px !important;width:13px !important;height:12px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCAxMic+PHJlY3QgeD0nMScgeT0nMScgd2lkdGg9JzEyJyBoZWlnaHQ9JzEwJyByeD0nMycgZmlsbD0nI0Y2RDNENicgc3Ryb2tlPScjZmZmJyBzdHJva2Utd2lkdGg9JzEuNCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}

/* 头像：俯视的马克杯——奶白一圈、杯沿可可棕，他的杯把在左、我的在右（朝外） */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] > :first-child[data-wk="avatar"]{box-shadow:0 0 0 4px #FFFCF7,0 0 0 7px #7A4E36,-27px 4px 0 -16.5px #F7F1EA,-27px 4px 0 -13px #7A4E36,0 6px 12px rgba(94,56,38,.18) !important}
[data-wk="msg"][data-me="1"] [data-wk="avatar"],[data-wk="cardrow"][data-me="1"] [data-wk="avatar"],[data-wk="rpsingle"] > [data-wk="rpcard"] + [data-wk="avatar"]{box-shadow:0 0 0 4px #FFFCF7,0 0 0 7px #7A4E36,27px 4px 0 -16.5px #F7F1EA,27px 4px 0 -13px #7A4E36,0 6px 12px rgba(94,56,38,.18) !important}

/* 气泡：他是一杯奶泡、顶上淌一圈可可；我是一杯可可、顶上一圈奶泡，泡上两颗小棉花糖 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:16px !important;line-height:1.6 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:url("data:image/svg+xml;base64,") 0 0/40px 12px repeat-x,#FFFCF7 !important;color:#4A3328 !important;padding:17px 16px 10px !important;box-shadow:0 3px 0 #EADBCB,0 6px 12px rgba(94,56,38,.1) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:url("data:image/svg+xml;base64,") 0 0/40px 12px repeat-x,linear-gradient(180deg,#7A4E36,#5E3826) !important;color:#fff !important;padding:17px 16px 10px !important;box-shadow:0 3px 0 #48291B,0 6px 12px rgba(94,56,38,.2) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:12px !important;top:-7px !important;width:48px !important;height:15px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:none !important}

/* 时间：两缕热气夹着 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#A8968A !important;font-size:11.5px !important;letter-spacing:.15em !important;display:inline-flex !important;align-items:center !important;gap:8px !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;width:14px !important;height:11px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAxNCcgZmlsbD0nbm9uZScgc3Ryb2tlPScjQTg5NjhBJyBzdHJva2Utd2lkdGg9JzEuMycgc3Ryb2tlLWxpbmVjYXA9J3JvdW5kJz48cGF0aCBkPSdNNSAxMyBxLTMgLTMgMCAtNiBxMyAtMyAwIC02Jy8+PHBhdGggZD0nTTEyIDEzIHEtMyAtMyAwIC02IHEzIC0zIDAgLTYnLz48L3N2Zz4=") center/contain no-repeat !important}
/* 已读：一颗巧克力豆；没读：一颗白棉花糖 */
[data-wk="meta"]{color:#A8968A !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:7px !important;height:7px !important;border-radius:50% 50% 50% 0 !important;background:#5E3826 !important;transform:rotate(-45deg) !important}
[data-wk="meta"][data-read="0"]::before{width:8px !important;height:7px !important;border-radius:2.5px !important;background:#fff !important;box-shadow:0 0 0 1px #EADBCB !important;transform:none !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#A8968A !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFCF7 !important;border:none !important;border-radius:16px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#7A4E36 !important}

/* 动描：一张牛皮纸小标签（不是杯子），前面一缕热气；我写的动作是粉色棉花糖标签，靠右 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;position:relative !important;background:#EFE2CF !important;border:none !important;border-radius:6px !important;box-shadow:none !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;color:#8A6A55 !important;opacity:1 !important;font-style:italic !important;font-size:12.5px !important;line-height:1.75 !important;padding:5px 14px 5px 28px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"" !important;position:absolute !important;left:9px !important;top:8px !important;width:13px !important;height:11px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAxNCcgZmlsbD0nbm9uZScgc3Ryb2tlPScjQTg5NjhBJyBzdHJva2Utd2lkdGg9JzEuMycgc3Ryb2tlLWxpbmVjYXA9J3JvdW5kJz48cGF0aCBkPSdNNSAxMyBxLTMgLTMgMCAtNiBxMyAtMyAwIC02Jy8+PHBhdGggZD0nTTEyIDEzIHEtMyAtMyAwIC02IHEzIC0zIDAgLTYnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="myactink"]{background:#FBE4E6 !important;color:#A86A70 !important;padding:5px 28px 5px 14px !important}
[data-wk="myactink"]::before{left:auto !important;right:9px !important}
/* 系统提示：一行小字，两头一颗棉花糖 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#A8968A !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}
[data-wk="sysnotetext"]::before{content:"▫ " !important;color:#7A4E36 !important}
[data-wk="sysnotetext"]::after{content:" ▫" !important;color:#7A4E36 !important}
[data-wk="narrbar"]{background:#FFF6EC !important;border-top:1px solid #EADBCB !important}
[data-wk="narrkind"]{border:1px solid #EADBCB !important;border-radius:999px !important;background:transparent !important;color:#A8968A !important}
[data-wk="narrkind"][data-on="1"]{background:#7A4E36 !important;border-color:#7A4E36 !important;color:#fff !important}

/* 底栏：一只奶白托盘；左棉花糖加号、奶色输入框、右可可杯发送、小勺回复 */
[data-wk="composer"]{background:#FFFCF7 !important;border-top:none !important;box-shadow:0 -3px 12px rgba(94,56,38,.1) !important;align-items:center !important;gap:8px !important;border-radius:20px 20px 0 0 !important}
[data-wk="chatinput"]{background:#F3EBE2 !important;border:none !important;border-radius:16px !important;color:#4A3328 !important}
[data-wk="chatinput"]::placeholder{color:#C2B2A5 !important}
[data-wk="chatplus"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:40px !important;min-width:40px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}

/* 打电话那一屏（语音）：一杯热可可的颜色，顶上一团奶泡色的光；按键是棉花糖块，挂断是一杯可可 */
[data-wk="call"][data-video="0"]{background:radial-gradient(ellipse at 50% 20%,rgba(255,246,236,.28),transparent 55%),linear-gradient(180deg,#7A4E36,#5E3826 60%,#3E2418) !important}
[data-wk="calltitle"]{color:#fff !important;font-weight:600 !important}
[data-wk="call"][data-video="0"] > button:first-child{background:rgba(255,255,255,.14) !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 6px #FFFCF7,0 0 0 11px #5E3826,0 0 0 12px rgba(255,255,255,.3),0 14px 30px rgba(0,0,0,.35) !important}
[data-wk="callbtns"] button > span:first-child{background:#fff !important;border-radius:30% !important;box-shadow:0 0 0 1px #EADBCB,0 5px 0 1px #F6D3D6,0 10px 18px rgba(0,0,0,.3) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#7A4E36 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:radial-gradient(circle at 50% 50%,#5E3826 0 55%,#7A4E36 56% 68%,#fff 69%) !important;border-radius:50% !important;box-shadow:0 5px 0 #3E2418,0 10px 18px rgba(0,0,0,.35) !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#fff !important}
[data-wk="callbubble"]{background:#FFFCF7 !important;color:#4A3328 !important;border:none !important;border-radius:16px !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:#FFF6EC !important;color:#5E3826 !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
